    }

    match url {
        Some(u) => { a.url = u; ParseResult::Args(Box::new(a)) }
        None => {
            let ctx = UsageContext {
                has_url: false,
                extra_positional: match required_option { Some(s) => vec![s], None => vec![] },
                show_options: required_option.is_none(),
            };
            ParseResult::UsageError(
                "the following required arguments were not provided:\n  <URL>".to_string(),
                ctx,
            )
        }
    }
}

fn value_err(flag: &str, val: &str, err: &str) -> ParseResult {
    ParseResult::UsageError(
        format!("invalid value '{}' for '{}': {}", val, flag, err),
        UsageContext { has_url: false, extra_positional: vec![], show_options: false },
    )
}

fn dup_err(flag: &str, has_url: bool) -> ParseResult {
    ParseResult::UsageError(
        format!("the argument '{}' cannot be used multiple times", flag),
        UsageContext { has_url, extra_positional: vec![], show_options: true },
    )
}

fn usage_err(msg: String, url: &Option<String>, req: Option<&'static str>) -> ParseResult {
    let ctx = UsageContext {
        has_url: url.is_some(),
        extra_positional: match req { Some(s) => vec![s], None => vec![] },
        show_options: true,
    };
    ParseResult::UsageError(msg, ctx)
}

/// Parse number with k/m suffix for -n flag.
fn parse_nreq(s: &str) -> Result<usize, String> {
    if let Some(rest) = s.strip_suffix('k').or_else(|| s.strip_suffix('K')) {
        rest.parse::<usize>()
            .map(|n| n * 1_000)
            .map_err(|e| e.to_string())
    } else if let Some(rest) = s.strip_suffix('m').or_else(|| s.strip_suffix('M')) {
        rest.parse::<usize>()
            .map(|n| n * 1_000_000)
            .map_err(|e| e.to_string())
    } else {
        s.parse::<usize>().map_err(|e| e.to_string())
    }
}

/// Parse duration string like "3s", "10ms", "500us", "2m", "1h".
fn parse_duration(s: &str) -> Result<Duration, String> {
    // Find split point between digits/dot and unit
    let mut split = 0usize;
    for (idx, ch) in s.char_indices() {
        if ch.is_ascii_digit() || ch == '.' {
            split = idx + ch.len_utf8();
        } else {
            break;
        }
    }
    if split == 0 {
        return Err("expected number at 0".to_string());
    }
    let num_str = &s[..split];
    let unit = &s[split..];
    let num: f64 = num_str.parse().map_err(|_| "expected number at 0".to_string())?;
    let secs: f64 = match unit {
        "ns" => num * 1e-9,
        "us" | "µs" => num * 1e-6,
        "ms" => num * 1e-3,
        "s" | "" => num,
        "m" => num * 60.0,
        "h" => num * 3600.0,
        "d" => num * 86400.0,
        _ => return Err(format!("unknown time unit '{}'", unit)),
    };
    if secs < 0.0 { return Err("negative duration".to_string()); }
    Ok(Duration::from_secs_f64(secs))
}

pub fn format_usage(exe: &str, ctx: &UsageContext) -> String {
    let mut s = format!("Usage: {}", exe);
    if ctx.show_options {
        s.push_str(" [OPTIONS]");
    }
    for opt in &ctx.extra_positional {
        s.push_str(&format!(" {}", opt));
    }
    s.push_str(" <URL>");
    s
}

pub fn print_help_to(exe: &str, out: &mut dyn std::io::Write) -> std::io::Result<()> {
    out.write_all(HELP_TEXT.replace("{EXE}", exe).as_bytes())
}

/// Called from main to handle a parse error: print to stderr and return exit code 2.
pub fn emit_usage_error(exe: &str, msg: &str, ctx: &UsageContext) -> ExitCode {
    eprintln!("error: {}\n", msg);
    eprintln!("{}\n", format_usage(exe, ctx));
    eprintln!("For more information, try '--help'.");
    ExitCode::from(2)
}
