// Minimal URL parser for http:// and https:// URLs.
use std::fmt;

#[derive(Debug, Clone)]
pub struct Url {
    pub scheme: String,
    pub host: String,
    pub port: Option<u16>,
    pub path: String,       // begins with '/', may contain '?query'
    pub userinfo: Option<String>,
}

#[derive(Debug)]
pub enum UrlError {
    RelativeWithoutBase,
    BadPort,
}

impl fmt::Display for UrlError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            UrlError::RelativeWithoutBase => write!(f, "relative URL without a base"),
            UrlError::BadPort => write!(f, "invalid port number"),
        }
    }
}

impl Url {
    pub fn parse(input: &str) -> Result<Self, UrlError> {
        // Check for scheme: text://
        let (scheme, rest) = match input.find("://") {
            Some(idx) => {
                let s = &input[..idx];
                if !s.chars().next().map(|c| c.is_ascii_alphabetic()).unwrap_or(false) {
                    return Err(UrlError::RelativeWithoutBase);
                }
                if !s.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.') {
                    return Err(UrlError::RelativeWithoutBase);
                }
                (s.to_ascii_lowercase(), &input[idx + 3..])
            }
            None => return Err(UrlError::RelativeWithoutBase),
        };

        // split off path/query at first '/' '?' '#'
        let (authority, path_q) = {
            let mut split = rest.len();
            for (i, c) in rest.char_indices() {
                if c == '/' || c == '?' || c == '#' {
                    split = i;
                    break;
                }
            }
            (&rest[..split], &rest[split..])
        };

        // userinfo@host:port
        let (userinfo, host_port) = match authority.rfind('@') {
            Some(i) => (Some(authority[..i].to_string()), &authority[i + 1..]),
            None => (None, authority),
        };

        // host may be "[ipv6]:port" or "host:port"
        let (host, port) = if host_port.starts_with('[') {
            let end = host_port.find(']').ok_or(UrlError::RelativeWithoutBase)?;
            let host = host_port[1..end].to_string();
            let rest = &host_port[end + 1..];
            let port = if rest.is_empty() {
                None
            } else if let Some(p) = rest.strip_prefix(':') {
                Some(p.parse::<u16>().map_err(|_| UrlError::BadPort)?)
            } else {
                return Err(UrlError::RelativeWithoutBase);
            };
            (host, port)
        } else {
            match host_port.rfind(':') {
                Some(i) => {
                    let h = host_port[..i].to_string();
                    let p = host_port[i + 1..].parse::<u16>().map_err(|_| UrlError::BadPort)?;
                    (h, Some(p))
                }
                None => (host_port.to_string(), None),
            }
        };

        let path = if path_q.is_empty() {
            "/".to_string()
        } else {
            path_q.to_string()
        };

        Ok(Url { scheme, host, port, path, userinfo })
    }

    pub fn default_port(&self) -> u16 {
        match self.scheme.as_str() {
            "https" => 443,
            "http" => 80,
            _ => 0,
        }
    }

    pub fn port_or_default(&self) -> u16 {
        self.port.unwrap_or_else(|| self.default_port())
    }

    pub fn host_header(&self) -> String {
        match self.port {
            Some(p) if p != self.default_port() => format!("{}:{}", self.host, p),
            _ => self.host.clone(),
        }
    }
}
