// Minimal HTTP/1.1 client using std::net::TcpStream.
use crate::url::Url;
use std::io::{self, Read, Write};
use std::net::{TcpStream, ToSocketAddrs, SocketAddr};
use std::time::{Duration, Instant};

#[derive(Debug, Clone)]
pub struct RequestSpec {
    pub method: String,
    pub url: Url,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
    pub timeout: Option<Duration>,
    pub connect_timeout: Duration,
}

#[derive(Debug)]
pub struct ResponseSummary {
    pub status: u16,
    pub bytes: usize,
    pub dns_lookup: Duration,
    pub dns_dialup: Duration,
    pub duration: Duration,
    pub start_rel: Duration,
}

#[derive(Debug)]
pub enum RequestError {
    Io(io::Error),
    Timeout,
    Protocol(String),
    ConnectionRefused,
    UnknownHost(String),
    TlsUnsupported,
}

impl std::fmt::Display for RequestError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RequestError::Io(e) => write!(f, "{}", e),
            RequestError::Timeout => write!(f, "timeout"),
            RequestError::Protocol(s) => write!(f, "{}", s),
            RequestError::ConnectionRefused => write!(f, "Connection refused (os error 111)"),
            RequestError::UnknownHost(h) => write!(f, "failed to lookup address information for '{}'", h),
            RequestError::TlsUnsupported => write!(f, "HTTPS is not supported in this build"),
        }
    }
}

impl From<io::Error> for RequestError {
    fn from(e: io::Error) -> Self {
        use io::ErrorKind::*;
        match e.kind() {
            TimedOut | WouldBlock => RequestError::Timeout,
            ConnectionRefused => RequestError::ConnectionRefused,
            _ => RequestError::Io(e),
        }
    }
}

pub fn perform(req: &RequestSpec, start_ref: Instant) -> (Result<ResponseSummary, RequestError>, Duration) {
    let req_start = Instant::now();
    let start_rel = req_start.saturating_duration_since(start_ref);

    if req.url.scheme == "https" {
        return (Err(RequestError::TlsUnsupported), start_rel);
    }

    let host = req.url.host.clone();
    let port = req.url.port_or_default();

    let dns_start = Instant::now();
    let addrs: Vec<SocketAddr> = match (host.as_str(), port).to_socket_addrs() {
        Ok(a) => a.collect(),
        Err(_) => return (Err(RequestError::UnknownHost(host)), start_rel),
    };
    let dns_lookup = dns_start.elapsed();
    if addrs.is_empty() {
        return (Err(RequestError::UnknownHost(host)), start_rel);
    }

    let mut stream = match TcpStream::connect_timeout(&addrs[0], req.connect_timeout) {
        Ok(s) => s,
        Err(e) => return (Err(RequestError::from(e)), start_rel),
    };
    let dns_dialup = dns_start.elapsed();

    if let Some(t) = req.timeout {
        let _ = stream.set_read_timeout(Some(t));
        let _ = stream.set_write_timeout(Some(t));
    }

    // Build request
    let path = &req.url.path;
    let mut buf = Vec::with_capacity(256);
    write!(buf, "{} {} HTTP/1.1\r\n", req.method, path).ok();
    // Host header first
    let mut has_host = false;
    for (k, _) in &req.headers {
        if k.eq_ignore_ascii_case("host") { has_host = true; break; }
    }
    if !has_host {
        write!(buf, "Host: {}\r\n", req.url.host_header()).ok();
    }
    for (k, v) in &req.headers {
        write!(buf, "{}: {}\r\n", k, v).ok();
    }
    if !req.body.is_empty() {
        write!(buf, "Content-Length: {}\r\n", req.body.len()).ok();
    }
    buf.extend_from_slice(b"\r\n");
    if !req.body.is_empty() {
        buf.extend_from_slice(&req.body);
    }

    if let Err(e) = stream.write_all(&buf) {
        return (Err(RequestError::from(e)), start_rel);
    }

    // Read response
    let mut reader = BufReader::new(stream);
    let (status, headers) = match read_headers(&mut reader) {
        Ok(x) => x,
        Err(e) => return (Err(e), start_rel),
    };

    // Determine body length
    let mut content_length: Option<usize> = None;
    let mut chunked = false;
    let mut close_conn = false;
    for (k, v) in &headers {
        if k.eq_ignore_ascii_case("content-length") {
            content_length = v.trim().parse().ok();
        } else if k.eq_ignore_ascii_case("transfer-encoding") {
            if v.to_ascii_lowercase().contains("chunked") { chunked = true; }
        } else if k.eq_ignore_ascii_case("connection") {
            if v.eq_ignore_ascii_case("close") { close_conn = true; }
        }
    }
    let _ = close_conn; // could be used for keep-alive logic

    let body_bytes = if chunked {
        match read_chunked(&mut reader) {
            Ok(n) => n,
            Err(e) => return (Err(e), start_rel),
        }
    } else if let Some(cl) = content_length {
        match reader.read_exact_count(cl) {
            Ok(n) => n,
            Err(e) => return (Err(e), start_rel),
        }
    } else if req.method.eq_ignore_ascii_case("HEAD") || (100..200).contains(&status) || status == 204 || status == 304 {
        0
    } else {
        match reader.read_to_end_count() {
            Ok(n) => n,
            Err(e) => return (Err(e), start_rel),
        }
    };

    let duration = req_start.elapsed();
    (Ok(ResponseSummary {
        status,
        bytes: body_bytes,
        dns_lookup,
        dns_dialup,
        duration,
        start_rel,
    }), start_rel)
}

struct BufReader<R: Read> {
    inner: R,
    buf: Vec<u8>,
    pos: usize,
}

impl<R: Read> BufReader<R> {
    fn new(inner: R) -> Self {
        Self { inner, buf: vec![0u8; 8192], pos: 0 }
    }
    fn fill(&mut self) -> io::Result<usize> {
        // discard consumed data
        if self.pos > 0 {
            self.buf.drain(0..self.pos);
            self.pos = 0;
        }
        let old = self.buf.len();
        self.buf.resize(old + 8192, 0);
        let n = self.inner.read(&mut self.buf[old..])?;
        self.buf.truncate(old + n);
        Ok(n)
    }
    fn read_line(&mut self) -> io::Result<Vec<u8>> {
        let mut out = Vec::new();
        loop {
            while self.pos < self.buf.len() {
                let b = self.buf[self.pos];
                self.pos += 1;
                out.push(b);
                if b == b'\n' {
                    return Ok(out);
                }
            }
            if self.fill()? == 0 {
                if out.is_empty() {
                    return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "eof"));
                }
                return Ok(out);
            }
        }
    }
    fn read_exact_count(&mut self, n: usize) -> Result<usize, RequestError> {
        let mut remaining = n;
        while remaining > 0 {
            let available = self.buf.len() - self.pos;
            if available == 0 {
                if self.fill().map_err(RequestError::from)? == 0 {
                    return Err(RequestError::Protocol("unexpected end of body".to_string()));
                }
                continue;
            }
            let take = available.min(remaining);
            self.pos += take;
            remaining -= take;
        }
        Ok(n)
    }
    fn read_to_end_count(&mut self) -> Result<usize, RequestError> {
        let mut total = 0usize;
        loop {
            let available = self.buf.len() - self.pos;
            total += available;
            self.pos = self.buf.len();
            let n = self.fill().map_err(RequestError::from)?;
            if n == 0 { return Ok(total); }
        }
    }
    fn skip(&mut self, n: usize) -> Result<(), RequestError> {
        let mut remaining = n;
        while remaining > 0 {
            let available = self.buf.len() - self.pos;
            if available == 0 {
                if self.fill().map_err(RequestError::from)? == 0 {
                    return Err(RequestError::Protocol("unexpected end of chunk".to_string()));
                }
                continue;
            }
            let take = available.min(remaining);
            self.pos += take;
            remaining -= take;
        }
        Ok(())
    }
}

fn read_headers<R: Read>(r: &mut BufReader<R>) -> Result<(u16, Vec<(String, String)>), RequestError> {
    let status_line = r.read_line().map_err(|e| RequestError::Protocol(format!("read status: {}", e)))?;
    let s = String::from_utf8_lossy(&status_line);
    let s = s.trim_end_matches(['\r', '\n']);
    let mut parts = s.splitn(3, ' ');
    let _version = parts.next().unwrap_or("");
    let status_str = parts.next().unwrap_or("0");
    let status: u16 = status_str.parse().map_err(|_| RequestError::Protocol(format!("bad status: {}", s)))?;
    let mut headers = Vec::new();
    loop {
        let line = r.read_line().map_err(|e| RequestError::Protocol(format!("read header: {}", e)))?;
        let line = String::from_utf8_lossy(&line);
        let line = line.trim_end_matches(['\r', '\n']);
        if line.is_empty() { break; }
        if let Some(idx) = line.find(':') {
            let k = line[..idx].to_string();
            let v = line[idx + 1..].trim().to_string();
            headers.push((k, v));
        }
    }
    Ok((status, headers))
}

fn read_chunked<R: Read>(r: &mut BufReader<R>) -> Result<usize, RequestError> {
    let mut total = 0usize;
    loop {
        let line = r.read_line().map_err(|e| RequestError::Protocol(format!("read chunk size: {}", e)))?;
        let line = String::from_utf8_lossy(&line);
        let hex = line.trim().split(';').next().unwrap_or("");
        let size = usize::from_str_radix(hex, 16).map_err(|_| RequestError::Protocol(format!("bad chunk size: {}", hex)))?;
        if size == 0 {
            // trailers
            loop {
                let l = r.read_line().map_err(|e| RequestError::Protocol(format!("trailer: {}", e)))?;
                let s = String::from_utf8_lossy(&l);
                let s = s.trim_end_matches(['\r', '\n']);
                if s.is_empty() { break; }
            }
            return Ok(total);
        }
        r.skip(size)?;
        total += size;
        // chunk trailing CRLF
        let _ = r.read_line();
    }
}
