fn read_headers<R: Read>(r: &mut BufReader<R>) -> Result<(u16, Vec<(String, String)>), RequestError> {
    let status_line = r.read_line().map_err(|e| RequestError::Protocol(format!("read status: {}", e)))?;
    let s = String::from_utf8_lossy(&status_line);
    let s = s.trim_end_matches(['\r', '\n']);
    let mut parts = s.splitn(3, ' ');
    let _version = parts.next().unwrap_or("");
    let status_str = parts.next().unwrap_or("0");
    let status: u16 = status_str.parse().map_err(|_| RequestError::Protocol(format!("bad status: {}", s)))?;
    let mut headers = Vec::new();
    loop {
        let line = r.read_line().map_err(|e| RequestError::Protocol(format!("read header: {}", e)))?;
        let line = String::from_utf8_lossy(&line);
        let line = line.trim_end_matches(['\r', '\n']);
        if line.is_empty() { break; }
        if let Some(idx) = line.find(':') {
            let k = line[..idx].to_string();
            let v = line[idx + 1..].trim().to_string();
            headers.push((k, v));
        }
    }
    Ok((status, headers))
}

fn read_chunked<R: Read>(r: &mut BufReader<R>) -> Result<usize, RequestError> {
    let mut total = 0usize;
    loop {
        let line = r.read_line().map_err(|e| RequestError::Protocol(format!("read chunk size: {}", e)))?;
        let line = String::from_utf8_lossy(&line);
        let hex = line.trim().split(';').next().unwrap_or("");
        let size = usize::from_str_radix(hex, 16).map_err(|_| RequestError::Protocol(format!("bad chunk size: {}", hex)))?;
        if size == 0 {
            // trailers
            loop {
                let l = r.read_line().map_err(|e| RequestError::Protocol(format!("trailer: {}", e)))?;
                let s = String::from_utf8_lossy(&l);
                let s = s.trim_end_matches(['\r', '\n']);
                if s.is_empty() { break; }
            }
            return Ok(total);
        }
        r.skip(size)?;
        total += size;
        // chunk trailing CRLF
        let _ = r.read_line();
    }
}
