// Statistics and output formatting for oha-like results.
use crate::args::{OutputFormat, TimeUnit};
use crate::http::{RequestError, ResponseSummary};
use std::collections::BTreeMap;
use std::io::Write;
use std::time::Duration;

pub struct Stats {
    pub total_duration: Duration,
    pub successes: Vec<ResponseSummary>,
    pub errors: Vec<(String, u64)>, // kept as map entries in aggregate
    pub status_counts: BTreeMap<u16, u64>,
}

pub struct AggregateResult {
    pub total_duration: Duration,
    pub n_attempted: u64,
    pub n_success: u64,
    pub bytes_total: u64,
    pub durations: Vec<f64>,        // seconds per successful request
    pub dns_dialup: Vec<f64>,        // seconds
    pub dns_lookup: Vec<f64>,        // seconds
    pub status_counts: BTreeMap<u16, u64>,
    pub error_counts: BTreeMap<String, u64>,
    pub size_per_request: Option<u64>, // if all successes have same size, or just average
    pub time_unit: Option<TimeUnit>,
}

impl AggregateResult {
    pub fn from_results(
        total_duration: Duration,
        results: &[(Result<ResponseSummary, RequestError>, Duration)],
        time_unit: Option<TimeUnit>,
    ) -> Self {
        let mut n_attempted = 0u64;
        let mut n_success = 0u64;
        let mut bytes_total: u64 = 0;
        let mut durations = Vec::new();
        let mut dns_dialup = Vec::new();
        let mut dns_lookup = Vec::new();
        let mut status_counts = BTreeMap::new();
        let mut error_counts: BTreeMap<String, u64> = BTreeMap::new();

        for (res, _start) in results {
            n_attempted += 1;
            match res {
                Ok(r) => {
                    n_success += 1;
                    bytes_total += r.bytes as u64;
                    durations.push(r.duration.as_secs_f64());
                    dns_dialup.push(r.dns_dialup.as_secs_f64());
                    dns_lookup.push(r.dns_lookup.as_secs_f64());
                    *status_counts.entry(r.status).or_insert(0) += 1;
                }
                Err(e) => {
                    *error_counts.entry(e.to_string()).or_insert(0) += 1;
                }
            }
        }

        // size per request — oha shows the single observed size (mode)
        let size_per_request = if n_success > 0 {
            Some(bytes_total / n_success)
        } else {
            None
        };

        AggregateResult {
            total_duration,
            n_attempted,
            n_success,
            bytes_total,
            durations,
            dns_dialup,
            dns_lookup,
            status_counts,
            error_counts,
            size_per_request,
            time_unit,
        }
    }

    pub fn success_rate(&self) -> f64 {
        if self.n_attempted == 0 { 0.0 } else { self.n_success as f64 / self.n_attempted as f64 }
    }

    pub fn rps(&self) -> f64 {
        self.n_attempted as f64 / self.total_duration.as_secs_f64()
    }
}

/// Determine automatic time unit based on total duration (in seconds).
fn auto_time_unit(total_secs: f64) -> TimeUnit {
    if total_secs >= 3600.0 { TimeUnit::H }
    else if total_secs >= 60.0 { TimeUnit::M }
    else if total_secs >= 1.0 { TimeUnit::S }
    else if total_secs >= 1e-3 { TimeUnit::Ms }
    else if total_secs >= 1e-6 { TimeUnit::Us }
    else { TimeUnit::Ns }
}

fn format_bytes(n: f64) -> String {
    if n.is_nan() { return "NaN".to_string(); }
    let units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    let mut val = n;
    let mut u = 0;
    while val >= 1024.0 && u < units.len() - 1 {
        val /= 1024.0;
        u += 1;
    }
    if u == 0 {
        format!("{:.0} {}", val, units[u])
    } else {
        format!("{:.2} {}", val, units[u])
    }
}

fn convert(t: f64, unit: TimeUnit) -> f64 {
    t / unit.seconds_per_unit()
}

fn fmt_time(t: f64, unit: TimeUnit) -> String {
    format!("{:.4} {}", convert(t, unit), unit.as_str())
}

pub fn write_text(out: &mut dyn Write, r: &AggregateResult, stats_success_breakdown: bool) -> std::io::Result<()> {
    let total_secs = r.total_duration.as_secs_f64();
    let unit = r.time_unit.unwrap_or_else(|| auto_time_unit(total_secs));

    let slowest = r.durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let fastest = r.durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let avg = if r.durations.is_empty() {
        f64::NAN
    } else {
        r.durations.iter().sum::<f64>() / r.durations.len() as f64
    };

    writeln!(out, "Summary:")?;
    writeln!(out, "  Success rate:\t{:.2}%", r.success_rate() * 100.0)?;
    writeln!(out, "  Total:\t{}", fmt_time(total_secs, unit))?;
    writeln!(out, "  Slowest:\t{}", fmt_time(slowest, unit))?;
    writeln!(out, "  Fastest:\t{}", fmt_time(fastest, unit))?;
    writeln!(out, "  Average:\t{}", fmt_time(avg, unit))?;
    writeln!(out, "  Requests/sec:\t{:.4}", r.rps())?;
    writeln!(out)?;
    writeln!(out, "  Total data:\t{}", format_bytes(r.bytes_total as f64))?;
    let sr = if r.n_success == 0 { "NaN".to_string() }
             else { format_bytes((r.bytes_total / r.n_success) as f64) };
    writeln!(out, "  Size/request:\t{}", sr)?;
    let sps = if total_secs > 0.0 { r.bytes_total as f64 / total_secs } else { 0.0 };
    writeln!(out, "  Size/sec:\t{}", format_bytes(sps))?;
    writeln!(out)?;

    // Histogram
    writeln!(out, "Response time histogram:")?;
    let (bins, counts) = histogram(&r.durations, 11);
    let max_count = counts.iter().copied().max().unwrap_or(0);
    // Find width for count
    let count_w = max_count.to_string().len();
    let unit_sec = unit.seconds_per_unit();
    for i in 0..bins.len() {
        let bar_len = if max_count == 0 { 0 } else { counts[i] * 32 / max_count };
        let bar: String = std::iter::repeat('■').take(bar_len as usize).collect();
        let bin_val = bins[i] / unit_sec;
        let label = if bin_val.is_nan() { format!("NaN {}", unit.as_str()) } else { format!("{:.3} {}", bin_val, unit.as_str()) };
        writeln!(out, "  {:>9} [{:>cw$}] |{}", label, counts[i], bar, cw = count_w)?;
    }
    writeln!(out)?;

    // Distribution
    writeln!(out, "Response time distribution:")?;
    let pcts: [(f64, &str); 9] = [
        (0.10, "10.00%"),(0.25, "25.00%"),(0.50, "50.00%"),(0.75, "75.00%"),(0.90, "90.00%"),
        (0.95, "95.00%"),(0.99, "99.00%"),(0.999, "99.90%"),(0.9999, "99.99%"),
    ];
    let sorted = sorted_copy(&r.durations);
    for (p, label) in &pcts {
        let v = percentile(&sorted, *p);
        writeln!(out, "  {} in {}", label, fmt_time(v, unit))?;
    }
    writeln!(out)?;
    writeln!(out)?;

    // Details
    writeln!(out, "Details (average, fastest, slowest):")?;
    let (avg_d, fast_d, slow_d) = stats3(&r.dns_dialup);
    writeln!(out, "  DNS+dialup:\t{}, {}, {}", fmt_time(avg_d, unit), fmt_time(fast_d, unit), fmt_time(slow_d, unit))?;
    let (avg_l, fast_l, slow_l) = stats3(&r.dns_lookup);
    writeln!(out, "  DNS-lookup:\t{}, {}, {}", fmt_time(avg_l, unit), fmt_time(fast_l, unit), fmt_time(slow_l, unit))?;
    writeln!(out)?;

    // Status codes
    if !r.status_counts.is_empty() {
        writeln!(out, "Status code distribution:")?;
        for (code, n) in &r.status_counts {
            writeln!(out, "  [{}] {} responses", code, n)?;
        }
    }
    if !r.error_counts.is_empty() {
        writeln!(out, "Error distribution:")?;
        for (e, n) in &r.error_counts {
            writeln!(out, "  [{}] {}", n, e)?;
        }
    }

    let _ = stats_success_breakdown;
    Ok(())
}

fn histogram(values: &[f64], n_bins: usize) -> (Vec<f64>, Vec<u64>) {
    if values.is_empty() {
        return (vec![f64::NAN; n_bins], vec![0; n_bins]);
    }
    let min = values.iter().cloned().fold(f64::INFINITY, f64::min);
    let max = values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let step = if n_bins <= 1 { 0.0 } else { (max - min) / (n_bins as f64 - 1.0) };
    let mut bins = Vec::with_capacity(n_bins);
    for i in 0..n_bins {
        bins.push(min + step * i as f64);
    }
    let mut counts = vec![0u64; n_bins];
    for &v in values {
        let idx = if step == 0.0 { 0 } else {
            (((v - min) / step).round() as isize).clamp(0, n_bins as isize - 1) as usize
        };
        counts[idx] += 1;
    }
    (bins, counts)
}

fn sorted_copy(values: &[f64]) -> Vec<f64> {
    let mut v = values.to_vec();
    v.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    v
}

fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() { return f64::NAN; }
    let idx = ((sorted.len() as f64) * p).ceil() as isize - 1;
    let idx = idx.clamp(0, sorted.len() as isize - 1) as usize;
    sorted[idx]
}

fn stats3(v: &[f64]) -> (f64, f64, f64) {
    if v.is_empty() { return (f64::NAN, f64::INFINITY, f64::NEG_INFINITY); }
    let avg = v.iter().sum::<f64>() / v.len() as f64;
    let fast = v.iter().cloned().fold(f64::INFINITY, f64::min);
    let slow = v.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    (avg, fast, slow)
}

/// Format a number for JSON (handling NaN/Inf as null).
fn json_num(v: f64) -> String {
    if v.is_nan() || v.is_infinite() {
        "null".to_string()
    } else if v == v.trunc() && v.abs() < 1e16 {
        // integer value
        format!("{}", v)
    } else {
        format!("{}", v)
    }
}

fn opt_num(v: Option<f64>) -> String {
    match v {
        Some(v) => json_num(v),
        None => "null".to_string(),
    }
}

pub fn write_json(out: &mut dyn Write, r: &AggregateResult) -> std::io::Result<()> {
    let total = r.total_duration.as_secs_f64();
    let slowest = if r.durations.is_empty() { None } else { Some(r.durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max)) };
    let fastest = if r.durations.is_empty() { None } else { Some(r.durations.iter().cloned().fold(f64::INFINITY, f64::min)) };
    let avg = if r.durations.is_empty() { None } else { Some(r.durations.iter().sum::<f64>() / r.durations.len() as f64) };
    let size_per_req = if r.n_success == 0 { None } else { Some(r.bytes_total / r.n_success) };

    writeln!(out, "{{")?;
    writeln!(out, "  \"summary\": {{")?;
    writeln!(out, "    \"successRate\": {},", json_num(r.success_rate()))?;
    writeln!(out, "    \"total\": {},", json_num(total))?;
    writeln!(out, "    \"slowest\": {},", opt_num(slowest))?;
    writeln!(out, "    \"fastest\": {},", opt_num(fastest))?;
    writeln!(out, "    \"average\": {},", opt_num(avg))?;
    writeln!(out, "    \"requestsPerSec\": {},", json_num(r.rps()))?;
    writeln!(out, "    \"totalData\": {},", r.bytes_total)?;
    match size_per_req {
        Some(v) => writeln!(out, "    \"sizePerRequest\": {},", v)?,
        None => writeln!(out, "    \"sizePerRequest\": null,")?,
    }
    let sps = if total > 0.0 { r.bytes_total as f64 / total } else { 0.0 };
    writeln!(out, "    \"sizePerSec\": {}", json_num(sps))?;
    writeln!(out, "  }},")?;

    // responseTimeHistogram
    let (bins, counts) = histogram(&r.durations, 11);
    writeln!(out, "  \"responseTimeHistogram\": {{")?;
    for i in 0..bins.len() {
        let label = if bins[i].is_nan() { "NaN".to_string() } else { format!("{}", bins[i]) };
        let comma = if i + 1 == bins.len() { "" } else { "," };
        writeln!(out, "    \"{}\": {}{}", label, counts[i], comma)?;
    }
    writeln!(out, "  }},")?;

    // latencyPercentiles
    let sorted = sorted_copy(&r.durations);
    let pct = |p: f64| -> String {
        if sorted.is_empty() { "null".to_string() } else { json_num(percentile(&sorted, p)) }
    };
    writeln!(out, "  \"latencyPercentiles\": {{")?;
    writeln!(out, "    \"p10\": {},", pct(0.10))?;
    writeln!(out, "    \"p25\": {},", pct(0.25))?;
    writeln!(out, "    \"p50\": {},", pct(0.50))?;
    writeln!(out, "    \"p75\": {},", pct(0.75))?;
    writeln!(out, "    \"p90\": {},", pct(0.90))?;
    writeln!(out, "    \"p95\": {},", pct(0.95))?;
    writeln!(out, "    \"p99\": {},", pct(0.99))?;
    writeln!(out, "    \"p99.9\": {},", pct(0.999))?;
    writeln!(out, "    \"p99.99\": {}", pct(0.9999))?;
    writeln!(out, "  }},")?;

    // rps (mean/stddev/min/max/percentiles)
    writeln!(out, "  \"rps\": {{")?;
    writeln!(out, "    \"mean\": null,")?;
    writeln!(out, "    \"stddev\": null,")?;
    writeln!(out, "    \"max\": null,")?;
    writeln!(out, "    \"min\": null,")?;
    writeln!(out, "    \"percentiles\": {{")?;
    writeln!(out, "      \"p10\": null,")?;
    writeln!(out, "      \"p25\": null,")?;
    writeln!(out, "      \"p50\": null,")?;
    writeln!(out, "      \"p75\": null,")?;
    writeln!(out, "      \"p90\": null,")?;
    writeln!(out, "      \"p95\": null,")?;
    writeln!(out, "      \"p99\": null,")?;
    writeln!(out, "      \"p99.9\": null,")?;
    writeln!(out, "      \"p99.99\": null")?;
    writeln!(out, "    }}")?;
    writeln!(out, "  }},")?;

    // details
    let (avg_d, fast_d, slow_d) = stats3(&r.dns_dialup);
    let (avg_l, fast_l, slow_l) = stats3(&r.dns_lookup);
    writeln!(out, "  \"details\": {{")?;
    writeln!(out, "    \"DNSDialup\": {{")?;
    writeln!(out, "      \"average\": {},", if r.dns_dialup.is_empty() { "null".to_string() } else { json_num(avg_d) })?;
    writeln!(out, "      \"fastest\": {},", if r.dns_dialup.is_empty() { "null".to_string() } else { json_num(fast_d) })?;
    writeln!(out, "      \"slowest\": {}", if r.dns_dialup.is_empty() { "null".to_string() } else { json_num(slow_d) })?;
    writeln!(out, "    }},")?;
    writeln!(out, "    \"DNSLookup\": {{")?;
    writeln!(out, "      \"average\": {},", if r.dns_lookup.is_empty() { "null".to_string() } else { json_num(avg_l) })?;
    writeln!(out, "      \"fastest\": {},", if r.dns_lookup.is_empty() { "null".to_string() } else { json_num(fast_l) })?;
    writeln!(out, "      \"slowest\": {}", if r.dns_lookup.is_empty() { "null".to_string() } else { json_num(slow_l) })?;
    writeln!(out, "    }}")?;
    writeln!(out, "  }},")?;

    // statusCodeDistribution
    write!(out, "  \"statusCodeDistribution\": {{")?;
    let n = r.status_counts.len();
    if n == 0 { write!(out, "}},")?; } else {
        writeln!(out)?;
        for (i, (code, count)) in r.status_counts.iter().enumerate() {
            let comma = if i + 1 == n { "" } else { "," };
            writeln!(out, "    \"{}\": {}{}", code, count, comma)?;
        }
        writeln!(out, "  }},")?;
    }

    // errorDistribution
    write!(out, "  \"errorDistribution\": {{")?;
    let n = r.error_counts.len();
    if n == 0 { write!(out, "}}")?; } else {
        writeln!(out)?;
        for (i, (e, count)) in r.error_counts.iter().enumerate() {
            let comma = if i + 1 == n { "" } else { "," };
            writeln!(out, "    \"{}\": {}{}", json_str_escape(e), count, comma)?;
        }
        write!(out, "  }}")?;
    }

    writeln!(out)?;
    write!(out, "}}")?;
    Ok(())
}

fn json_str_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

pub fn write_output(
    out: &mut dyn Write,
    fmt: OutputFormat,
    r: &AggregateResult,
    stats_success_breakdown: bool,
) -> std::io::Result<()> {
    match fmt {
        OutputFormat::Text => write_text(out, r, stats_success_breakdown),
        OutputFormat::Json => write_json(out, r),
        OutputFormat::Quiet => Ok(()),
        OutputFormat::Csv => Ok(()), // CSV is streamed per-request; no final output here
    }
}
