    else if total_secs >= 1e-6 { TimeUnit::Us }
    else { TimeUnit::Ns }
}

fn format_bytes(n: f64) -> String {
    if n.is_nan() { return "NaN".to_string(); }
    let units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    let mut val = n;
    let mut u = 0;
    while val >= 1024.0 && u < units.len() - 1 {
        val /= 1024.0;
        u += 1;
    }
    if u == 0 {
        format!("{:.0} {}", val, units[u])
    } else {
        format!("{:.2} {}", val, units[u])
    }
}

fn convert(t: f64, unit: TimeUnit) -> f64 {
    t / unit.seconds_per_unit()
}

fn fmt_time(t: f64, unit: TimeUnit) -> String {
    format!("{:.4} {}", convert(t, unit), unit.as_str())
}

pub fn write_text(out: &mut dyn Write, r: &AggregateResult, stats_success_breakdown: bool) -> std::io::Result<()> {
    let total_secs = r.total_duration.as_secs_f64();
    let unit = r.time_unit.unwrap_or_else(|| auto_time_unit(total_secs));

    let slowest = r.durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let fastest = r.durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let avg = if r.durations.is_empty() {
        f64::NAN
    } else {
        r.durations.iter().sum::<f64>() / r.durations.len() as f64
    };

    writeln!(out, "Summary:")?;
    writeln!(out, "  Success rate:\t{:.2}%", r.success_rate() * 100.0)?;
    writeln!(out, "  Total:\t{}", fmt_time(total_secs, unit))?;
    writeln!(out, "  Slowest:\t{}", fmt_time(slowest, unit))?;
    writeln!(out, "  Fastest:\t{}", fmt_time(fastest, unit))?;
    writeln!(out, "  Average:\t{}", fmt_time(avg, unit))?;
    writeln!(out, "  Requests/sec:\t{:.4}", r.rps())?;
    writeln!(out)?;
    writeln!(out, "  Total data:\t{}", format_bytes(r.bytes_total as f64))?;
    let sr = if r.n_success == 0 { "NaN".to_string() }
             else { format_bytes((r.bytes_total / r.n_success) as f64) };
    writeln!(out, "  Size/request:\t{}", sr)?;
    let sps = if total_secs > 0.0 { r.bytes_total as f64 / total_secs } else { 0.0 };
