        let bar_len = if max_count == 0 { 0 } else { counts[i] * 32 / max_count };
        let bar: String = std::iter::repeat('■').take(bar_len as usize).collect();
        let bin_val = bins[i] / unit_sec;
        let label = if bin_val.is_nan() { format!("NaN {}", unit.as_str()) } else { format!("{:.3} {}", bin_val, unit.as_str()) };
        writeln!(out, "  {:>9} [{:>cw$}] |{}", label, counts[i], bar, cw = count_w)?;
    }
    writeln!(out)?;

