    writeln!(out, "Response time distribution:")?;
    let pcts: [(f64, &str); 9] = [
        (0.10, "10.00%"),(0.25, "25.00%"),(0.50, "50.00%"),(0.75, "75.00%"),(0.90, "90.00%"),
