    Ok(())
}

fn json_str_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

pub fn write_output(
    out: &mut dyn Write,
    fmt: OutputFormat,
    r: &AggregateResult,
    stats_success_breakdown: bool,
) -> std::io::Result<()> {
    match fmt {
        OutputFormat::Text => write_text(out, r, stats_success_breakdown),
        OutputFormat::Json => write_json(out, r),
        OutputFormat::Quiet => Ok(()),
        OutputFormat::Csv => Ok(()), // CSV is streamed per-request; no final output here
    }
}
