fn histogram(values: &[f64], n_bins: usize) -> (Vec<f64>, Vec<u64>) {
    if values.is_empty() {
        return (vec![f64::NAN; n_bins], vec![0; n_bins]);
    }
    let min = values.iter().cloned().fold(f64::INFINITY, f64::min);
    let max = values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let step = if n_bins <= 1 { 0.0 } else { (max - min) / (n_bins as f64 - 1.0) };
    let mut bins = Vec::with_capacity(n_bins);
    for i in 0..n_bins {
        bins.push(min + step * i as f64);
    }
    let mut counts = vec![0u64; n_bins];
    for &v in values {
        let idx = if step == 0.0 { 0 } else {
            (((v - min) / step).round() as isize).clamp(0, n_bins as isize - 1) as usize
        };
        counts[idx] += 1;
    }
    (bins, counts)
}

fn sorted_copy(values: &[f64]) -> Vec<f64> {
    let mut v = values.to_vec();
    v.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    v
}

fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() { return f64::NAN; }
    let idx = ((sorted.len() as f64) * p).ceil() as isize - 1;
    let idx = idx.clamp(0, sorted.len() as isize - 1) as usize;
    sorted[idx]
}

fn stats3(v: &[f64]) -> (f64, f64, f64) {
    if v.is_empty() { return (f64::NAN, f64::INFINITY, f64::NEG_INFINITY); }
    let avg = v.iter().sum::<f64>() / v.len() as f64;
    let fast = v.iter().cloned().fold(f64::INFINITY, f64::min);
    let slow = v.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    (avg, fast, slow)
}

/// Format a number for JSON (handling NaN/Inf as null).
fn json_num(v: f64) -> String {
    if v.is_nan() || v.is_infinite() {
        "null".to_string()
    } else if v == v.trunc() && v.abs() < 1e16 {
        // integer value
        format!("{}", v)
    } else {
        format!("{}", v)
    }
}

fn opt_num(v: Option<f64>) -> String {
    match v {
        Some(v) => json_num(v),
        None => "null".to_string(),
    }
}

