    let total = r.total_duration.as_secs_f64();
    let slowest = if r.durations.is_empty() { None } else { Some(r.durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max)) };
    let fastest = if r.durations.is_empty() { None } else { Some(r.durations.iter().cloned().fold(f64::INFINITY, f64::min)) };
    let avg = if r.durations.is_empty() { None } else { Some(r.durations.iter().sum::<f64>() / r.durations.len() as f64) };
    let size_per_req = if r.n_success == 0 { None } else { Some(r.bytes_total / r.n_success) };

    writeln!(out, "{{")?;
    writeln!(out, "  \"summary\": {{")?;
    writeln!(out, "    \"successRate\": {},", json_num(r.success_rate()))?;
    writeln!(out, "    \"total\": {},", json_num(total))?;
    writeln!(out, "    \"slowest\": {},", opt_num(slowest))?;
    writeln!(out, "    \"fastest\": {},", opt_num(fastest))?;
    writeln!(out, "    \"average\": {},", opt_num(avg))?;
    writeln!(out, "    \"requestsPerSec\": {},", json_num(r.rps()))?;
    writeln!(out, "    \"totalData\": {},", r.bytes_total)?;
