// Statistics and output formatting for oha-like results.
use crate::args::{OutputFormat, TimeUnit};
use crate::http::{RequestError, ResponseSummary};
use std::collections::BTreeMap;
use std::io::Write;
use std::time::Duration;

pub struct Stats {
    pub total_duration: Duration,
    pub successes: Vec<ResponseSummary>,
    pub errors: Vec<(String, u64)>, // kept as map entries in aggregate
    pub status_counts: BTreeMap<u16, u64>,
}

pub struct AggregateResult {
    pub total_duration: Duration,
    pub n_attempted: u64,
    pub n_success: u64,
    pub bytes_total: u64,
    pub durations: Vec<f64>,        // seconds per successful request
    pub dns_dialup: Vec<f64>,        // seconds
    pub dns_lookup: Vec<f64>,        // seconds
    pub status_counts: BTreeMap<u16, u64>,
    pub error_counts: BTreeMap<String, u64>,
    pub size_per_request: Option<u64>, // if all successes have same size, or just average
    pub time_unit: Option<TimeUnit>,
}

impl AggregateResult {
    pub fn from_results(
        total_duration: Duration,
        results: &[(Result<ResponseSummary, RequestError>, Duration)],
        time_unit: Option<TimeUnit>,
    ) -> Self {
        let mut n_attempted = 0u64;
        let mut n_success = 0u64;
        let mut bytes_total: u64 = 0;
        let mut durations = Vec::new();
        let mut dns_dialup = Vec::new();
        let mut dns_lookup = Vec::new();
        let mut status_counts = BTreeMap::new();
        let mut error_counts: BTreeMap<String, u64> = BTreeMap::new();

        for (res, _start) in results {
            n_attempted += 1;
            match res {
                Ok(r) => {
                    n_success += 1;
                    bytes_total += r.bytes as u64;
                    durations.push(r.duration.as_secs_f64());
                    dns_dialup.push(r.dns_dialup.as_secs_f64());
                    dns_lookup.push(r.dns_lookup.as_secs_f64());
                    *status_counts.entry(r.status).or_insert(0) += 1;
                }
                Err(e) => {
                    *error_counts.entry(e.to_string()).or_insert(0) += 1;
                }
            }
        }

        // size per request — oha shows the single observed size (mode)
        let size_per_request = if n_success > 0 {
            Some(bytes_total / n_success)
        } else {
            None
        };

        AggregateResult {
            total_duration,
            n_attempted,
            n_success,
            bytes_total,
            durations,
            dns_dialup,
            dns_lookup,
            status_counts,
            error_counts,
            size_per_request,
            time_unit,
        }
    }

    pub fn success_rate(&self) -> f64 {
        if self.n_attempted == 0 { 0.0 } else { self.n_success as f64 / self.n_attempted as f64 }
    }

    pub fn rps(&self) -> f64 {
        self.n_attempted as f64 / self.total_duration.as_secs_f64()
    }
}

/// Determine automatic time unit based on total duration (in seconds).
fn auto_time_unit(total_secs: f64) -> TimeUnit {
    if total_secs >= 3600.0 { TimeUnit::H }
    else if total_secs >= 60.0 { TimeUnit::M }
    else if total_secs >= 1.0 { TimeUnit::S }
    else if total_secs >= 1e-3 { TimeUnit::Ms }
    else if total_secs >= 1e-6 { TimeUnit::Us }
    else { TimeUnit::Ns }
}

fn format_bytes(n: f64) -> String {
    if n.is_nan() { return "NaN".to_string(); }
    let units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    let mut val = n;
    let mut u = 0;
    while val >= 1024.0 && u < units.len() - 1 {
        val /= 1024.0;
        u += 1;
    }
    if u == 0 {
        format!("{:.0} {}", val, units[u])
    } else {
        format!("{:.2} {}", val, units[u])
    }
}

fn convert(t: f64, unit: TimeUnit) -> f64 {
    t / unit.seconds_per_unit()
}

fn fmt_time(t: f64, unit: TimeUnit) -> String {
    format!("{:.4} {}", convert(t, unit), unit.as_str())
}

