    writeln!(out, "  \"rps\": {{")?;
    writeln!(out, "    \"mean\": null,")?;
    writeln!(out, "    \"stddev\": null,")?;
    writeln!(out, "    \"max\": null,")?;
    writeln!(out, "    \"min\": null,")?;
    writeln!(out, "    \"percentiles\": {{")?;
    writeln!(out, "      \"p10\": null,")?;
    writeln!(out, "      \"p25\": null,")?;
    writeln!(out, "      \"p50\": null,")?;
    writeln!(out, "      \"p75\": null,")?;
    writeln!(out, "      \"p90\": null,")?;
    writeln!(out, "      \"p95\": null,")?;
    writeln!(out, "      \"p99\": null,")?;
    writeln!(out, "      \"p99.9\": null,")?;
    writeln!(out, "      \"p99.99\": null")?;
    writeln!(out, "    }}")?;
    writeln!(out, "  }},")?;

    // details
    let (avg_d, fast_d, slow_d) = stats3(&r.dns_dialup);
    let (avg_l, fast_l, slow_l) = stats3(&r.dns_lookup);
    writeln!(out, "  \"details\": {{")?;
    writeln!(out, "    \"DNSDialup\": {{")?;
    writeln!(out, "      \"average\": {},", if r.dns_dialup.is_empty() { "null".to_string() } else { json_num(avg_d) })?;
    writeln!(out, "      \"fastest\": {},", if r.dns_dialup.is_empty() { "null".to_string() } else { json_num(fast_d) })?;
    writeln!(out, "      \"slowest\": {}", if r.dns_dialup.is_empty() { "null".to_string() } else { json_num(slow_d) })?;
    writeln!(out, "    }},")?;
    writeln!(out, "    \"DNSLookup\": {{")?;
    writeln!(out, "      \"average\": {},", if r.dns_lookup.is_empty() { "null".to_string() } else { json_num(avg_l) })?;
    writeln!(out, "      \"fastest\": {},", if r.dns_lookup.is_empty() { "null".to_string() } else { json_num(fast_l) })?;
    writeln!(out, "      \"slowest\": {}", if r.dns_lookup.is_empty() { "null".to_string() } else { json_num(slow_l) })?;
    writeln!(out, "    }}")?;
    writeln!(out, "  }},")?;

    // statusCodeDistribution
    write!(out, "  \"statusCodeDistribution\": {{")?;
    let n = r.status_counts.len();
    if n == 0 { write!(out, "}},")?; } else {
        writeln!(out)?;
        for (i, (code, count)) in r.status_counts.iter().enumerate() {
            let comma = if i + 1 == n { "" } else { "," };
            writeln!(out, "    \"{}\": {}{}", code, count, comma)?;
        }
        writeln!(out, "  }},")?;
    }

    // errorDistribution
    write!(out, "  \"errorDistribution\": {{")?;
    let n = r.error_counts.len();
    if n == 0 { write!(out, "}}")?; } else {
        writeln!(out)?;
        for (i, (e, count)) in r.error_counts.iter().enumerate() {
            let comma = if i + 1 == n { "" } else { "," };
            writeln!(out, "    \"{}\": {}{}", json_str_escape(e), count, comma)?;
        }
        write!(out, "  }}")?;
    }

    writeln!(out)?;
    write!(out, "}}")?;
    Ok(())
}

fn json_str_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

pub fn write_output(
    out: &mut dyn Write,
    fmt: OutputFormat,
    r: &AggregateResult,
    stats_success_breakdown: bool,
) -> std::io::Result<()> {
    match fmt {
        OutputFormat::Text => write_text(out, r, stats_success_breakdown),
        OutputFormat::Json => write_json(out, r),
        OutputFormat::Quiet => Ok(()),
        OutputFormat::Csv => Ok(()), // CSV is streamed per-request; no final output here
    }
}
