use url::Url as MyUrl;

const VERSION: &str = "1.12.1";

fn exe_name() -> String {
    std::env::args().next()
        .and_then(|s| PathBuf::from(s).file_name().map(|n| n.to_string_lossy().to_string()))
        .unwrap_or_else(|| "oha".to_string())
}

fn main() -> ExitCode {
