        eprintln!("Error: HTTPS is not supported in this build");
        return ExitCode::from(1);
    }
    if url.scheme != "http" {
        eprintln!("Error: unsupported URL scheme: {}", url.scheme);
        return ExitCode::from(1);
    }

    // Build request headers
    let mut headers: Vec<(String, String)> = Vec::new();
    // default headers
    if let Some(ref ah) = a.accept_header {
        headers.push(("Accept".into(), ah.clone()));
    } else {
        headers.push(("accept".into(), "*/*".into()));
    }
    if !a.disable_compression {
        headers.push(("accept-encoding".into(), "gzip, compress, deflate, br".into()));
    }
    headers.push(("user-agent".into(), format!("oha/{}", VERSION)));
    if let Some(ref h) = a.host {
        headers.push(("host".into(), h.clone()));
    }
    for h in &a.headers {
        if let Some(idx) = h.find(':') {
            headers.push((h[..idx].trim().to_string(), h[idx + 1..].trim().to_string()));
        }
    }
    if let Some(ref ct) = a.content_type {
        headers.push(("content-type".into(), ct.clone()));
    }
    if a.disable_keepalive {
        headers.push(("connection".into(), "close".into()));
    }
    // basic auth
    if let Some(ref ba) = a.basic_auth {
        let enc = base64_encode(ba.as_bytes());
        headers.push(("authorization".into(), format!("Basic {}", enc)));
    }

    // Request body
    let body: Vec<u8> = if let Some(ref s) = a.body_string {
        s.as_bytes().to_vec()
    } else if let Some(ref p) = a.body_path {
