        println!("        data: Some({} bytes),", spec.body.len());
        println!("    }},");
    }
    println!("}}");
}

fn run_load(a: &Args, spec: &RequestSpec) -> ExitCode {
    let start = Instant::now();
    let deadline = a.duration.map(|d| start + d);
    let total = a.n_requests;
    let concurrency = a.n_connections.max(1);

    // Shared state
    let remaining = Arc::new(Mutex::new(total as i64));
    let results: Arc<Mutex<Vec<(Result<http::ResponseSummary, RequestError>, Duration)>>> = Arc::new(Mutex::new(Vec::with_capacity(total)));

    // CSV output streaming (per request) - if output format is csv.
    let csv_writer: Arc<Mutex<Option<Box<dyn Write + Send>>>> = if a.output_format == OutputFormat::Csv {
        let w: Box<dyn Write + Send> = match &a.output {
            Some(p) => Box::new(std::fs::File::create(p).expect("open output")),
            None => Box::new(std::io::stdout()),
        };
        Arc::new(Mutex::new(Some(w)))
    } else {
        Arc::new(Mutex::new(None))
    };

    let mut handles = Vec::new();
    for _ in 0..concurrency {
        let remaining = Arc::clone(&remaining);
        let results = Arc::clone(&results);
        let csv_writer = Arc::clone(&csv_writer);
        let spec = spec.clone();
        let deadline = deadline;
        handles.push(thread::spawn(move || {
            loop {
                if let Some(d) = deadline {
                    if Instant::now() >= d { break; }
                }
                {
                    let mut r = remaining.lock().unwrap();
                    if *r <= 0 { break; }
                    *r -= 1;
                }
                let (res, start_rel) = perform(&spec, start);
                // write CSV row
                if let Ok(mut guard) = csv_writer.lock() {
                    if let Some(w) = guard.as_mut() {
                        match &res {
                            Ok(r) => {
                                let _ = writeln!(
                                    w,
                                    "{:.9},{:.9},{:.9},{:.9},{:.9},{},{}",
                                    start_rel.as_secs_f64(),
                                    r.dns_lookup.as_secs_f64(),
                                    r.dns_dialup.as_secs_f64(),
                                    r.duration.as_secs_f64(),
                                    r.duration.as_secs_f64(),
                                    r.bytes,
                                    r.status,
                                );
                            }
                            Err(_) => {}
                        }
                    }
                }
                results.lock().unwrap().push((res, start_rel));
            }
        }));
    }

    for h in handles { let _ = h.join(); }

    let total_duration = start.elapsed();
    let guard = results.lock().unwrap();
    let agg = AggregateResult::from_results(total_duration, &guard, a.time_unit);

    // Final output
    let mut out: Box<dyn Write> = match &a.output {
        Some(p) if a.output_format != OutputFormat::Csv => {
            Box::new(std::fs::File::create(p).expect("open output"))
        }
        _ => Box::new(std::io::stdout()),
    };

    match a.output_format {
        OutputFormat::Csv => { /* already streamed */ }
        OutputFormat::Quiet => { /* no output */ }
        fmt => { let _ = write_output(&mut *out, fmt, &agg, a.stats_success_breakdown); }
    }

    ExitCode::SUCCESS
}

// Minimal base64 encoder for Basic auth.
fn base64_encode(data: &[u8]) -> String {
    const ALPH: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
    let mut i = 0;
    while i + 3 <= data.len() {
        let b = (data[i] as u32) << 16 | (data[i + 1] as u32) << 8 | (data[i + 2] as u32);
        out.push(ALPH[((b >> 18) & 0x3f) as usize] as char);
        out.push(ALPH[((b >> 12) & 0x3f) as usize] as char);
        out.push(ALPH[((b >> 6) & 0x3f) as usize] as char);
        out.push(ALPH[(b & 0x3f) as usize] as char);
        i += 3;
    }
    let rem = data.len() - i;
    if rem == 1 {
        let b = (data[i] as u32) << 16;
        out.push(ALPH[((b >> 18) & 0x3f) as usize] as char);
        out.push(ALPH[((b >> 12) & 0x3f) as usize] as char);
        out.push('=');
        out.push('=');
    } else if rem == 2 {
        let b = (data[i] as u32) << 16 | (data[i + 1] as u32) << 8;
        out.push(ALPH[((b >> 18) & 0x3f) as usize] as char);
        out.push(ALPH[((b >> 12) & 0x3f) as usize] as char);
        out.push(ALPH[((b >> 6) & 0x3f) as usize] as char);
        out.push('=');
    }
    out
}
