fn run_load(a: &Args, spec: &RequestSpec) -> ExitCode {
    let start = Instant::now();
    let deadline = a.duration.map(|d| start + d);
    let total = a.n_requests;
    let concurrency = a.n_connections.max(1);

    // Shared state
    let remaining = Arc::new(Mutex::new(total as i64));
