#[derive(Debug, Clone, Copy, PartialEq)]
pub enum TimeUnit { Ns, Us, Ms, S, M, H }

impl TimeUnit {
    pub fn as_str(&self) -> &'static str {
        match self { TimeUnit::Ns => "ns", TimeUnit::Us => "us", TimeUnit::Ms => "ms",
                     TimeUnit::S => "s", TimeUnit::M => "m", TimeUnit::H => "h" }
    }
    pub fn seconds_per_unit(&self) -> f64 {
        match self { TimeUnit::Ns => 1e-9, TimeUnit::Us => 1e-6, TimeUnit::Ms => 1e-3,
                     TimeUnit::S => 1.0, TimeUnit::M => 60.0, TimeUnit::H => 3600.0 }
    }
}

pub enum ParseResult {
    Args(Box<Args>),
    Help,
    Version,
    UsageError(String, UsageContext),
    /// Raised when no arguments are supplied; prints full help to stderr + exit 2.
    EmptyArgsError,
}

#[derive(Clone, Debug, Default)]
pub struct UsageContext {
    pub show_usage: bool,           // whether to include the Usage: line
    pub show_options: bool,          // [OPTIONS] part in Usage
    pub extra_positional: Vec<String>, // extra required args in Usage
}

pub fn parse_args(argv: &[String]) -> ParseResult {
    if argv.is_empty() {
        return ParseResult::EmptyArgsError;
    }

    let mut url: Option<String> = None;
    let mut a = Args {
        url: String::new(),
        n_requests: 200,
        n_connections: 50,
        n_http2_parallel: 1,
        duration: None,
        wait_ongoing: false,
        qps: None,
        burst_delay: None,
        burst_rate: None,
        rand_regex_url: false,
        urls_from_file: false,
        max_repeat: 4,
        dump_urls: None,
        latency_correction: false,
        no_tui: false,
        fps: 16,
        method: "GET".to_string(),
        headers: vec![],
        proxy_headers: vec![],
        timeout: None,
        connect_timeout: Duration::from_secs(5),
        accept_header: None,
        body_string: None,
        body_path: None,
        body_path_lines: None,
        form: vec![],
        content_type: None,
        basic_auth: None,
        aws_session: None,
        aws_sigv4: None,
        proxy: None,
        proxy_http_version: None,
        proxy_http2: false,
        http_version: None,
        http2: false,
        host: None,
        disable_compression: false,
        redirect: 10,
        disable_keepalive: false,
        no_pre_lookup: false,
        ipv6: false,
        ipv4: false,
        cacert: None,
        cert: None,
        key: None,
        insecure: false,
        connect_to: vec![],
        no_color: std::env::var("NO_COLOR").is_ok(),
        unix_socket: None,
        stats_success_breakdown: false,
        db_url: None,
        debug: false,
        output: None,
        output_format: OutputFormat::Text,
        time_unit: None,
    };

    let mut seen_output_format = false;
    let mut seen_disable_keepalive = false;
    let mut seen_http2 = false;
    let mut seen_debug = false;
    let mut required_option: Option<String> = None;

    let mut i = 0;
    let mut positional_only = false;

    while i < argv.len() {
        let arg = &argv[i];

        if !positional_only && arg == "--" {
            positional_only = true;
            i += 1;
            continue;
        }

        if !positional_only && (arg == "--help" || arg == "-h") {
            return ParseResult::Help;
        }
        if !positional_only && (arg == "--version" || arg == "-V") {
            return ParseResult::Version;
        }

        if positional_only {
            if url.is_none() { url = Some(arg.clone()); i += 1; continue; }
            return unexpected(arg, url.is_some());
        }

        let (key, eq_val): (String, Option<String>) = if arg.starts_with("--") {
            if let Some(idx) = arg.find('=') {
                (arg[..idx].to_string(), Some(arg[idx + 1..].to_string()))
            } else { (arg.clone(), None) }
        } else { (arg.clone(), None) };

        macro_rules! take_val {
            ($name:expr) => {{
                if let Some(v) = eq_val.clone() { v }
                else {
                    i += 1;
                    if i >= argv.len() {
                        return ParseResult::UsageError(
                            format!("a value is required for '{}' but none was supplied", $name),
                            UsageContext { show_usage: false, ..Default::default() },
                        );
                    }
                    argv[i].clone()
                }
            }};
        }

        match key.as_str() {
            "-n" => { let v = take_val!("-n <N_REQUESTS>");
                a.n_requests = match parse_nreq(&v) { Ok(n)=>n, Err(e)=>return value_err("-n <N_REQUESTS>", &v, &e) };
                if url.is_none() { required_option = Some("-n <N_REQUESTS>".to_string()); }
            }
            "-c" => { let v = take_val!("-c <N_CONNECTIONS>");
                a.n_connections = match v.parse::<usize>() { Ok(n)=>n, Err(e)=>return value_err("-c <N_CONNECTIONS>", &v, &e.to_string()) };
                if url.is_none() { required_option = Some("-c <N_CONNECTIONS>".to_string()); }
            }
            "-p" => { let v = take_val!("-p <N_HTTP2_PARALLEL>");
                a.n_http2_parallel = match v.parse::<usize>() { Ok(n)=>n, Err(e)=>return value_err("-p <N_HTTP2_PARALLEL>", &v, &e.to_string()) };
                if url.is_none() { required_option = Some("-p <N_HTTP2_PARALLEL>".to_string()); }
            }
            "-z" => { let v = take_val!("-z <DURATION>");
                a.duration = Some(match parse_duration(&v) { Ok(d)=>d, Err(e)=>return value_err("-z <DURATION>", &v, &e) });
                if url.is_none() { required_option = Some("-z <DURATION>".to_string()); }
            }
            "-w" | "--wait-ongoing-requests-after-deadline" => { a.wait_ongoing = true; }
            "-q" => { let v = take_val!("-q <QUERY_PER_SECOND>");
                a.qps = Some(match v.parse::<usize>() { Ok(n)=>n, Err(e)=>return value_err("-q <QUERY_PER_SECOND>", &v, &e.to_string()) });
                if url.is_none() { required_option = Some("-q <QUERY_PER_SECOND>".to_string()); }
            }
            "--burst-delay" => { let v = take_val!("--burst-delay <BURST_DURATION>");
                a.burst_delay = Some(match parse_duration(&v) { Ok(d)=>d, Err(e)=>return value_err("--burst-delay <BURST_DURATION>", &v, &e) }); }
            "--burst-rate" => { let v = take_val!("--burst-rate <BURST_REQUESTS>");
                a.burst_rate = Some(match v.parse::<usize>() { Ok(n)=>n, Err(e)=>return value_err("--burst-rate <BURST_REQUESTS>", &v, &e.to_string()) }); }
            "--rand-regex-url" => { a.rand_regex_url = true; }
            "--urls-from-file" => { a.urls_from_file = true; }
            "--max-repeat" => { let v = take_val!("--max-repeat <MAX_REPEAT>");
                a.max_repeat = match v.parse::<u32>() { Ok(n)=>n, Err(e)=>return value_err("--max-repeat <MAX_REPEAT>", &v, &e.to_string()) }; }
            "--dump-urls" => { let v = take_val!("--dump-urls <DUMP_URLS>");
                a.dump_urls = Some(match v.parse::<usize>() { Ok(n)=>n, Err(e)=>return value_err("--dump-urls <DUMP_URLS>", &v, &e.to_string()) }); }
            "--latency-correction" => { a.latency_correction = true; }
            "--no-tui" => { a.no_tui = true; }
            "--fps" => { let v = take_val!("--fps <FPS>");
                a.fps = match v.parse::<usize>() { Ok(n)=>n, Err(e)=>return value_err("--fps <FPS>", &v, &e.to_string()) }; }
            "-m" | "--method" => { a.method = take_val!("--method <METHOD>"); }
            "-H" => { let v = take_val!("-H <HEADERS>"); a.headers.push(v); }
            "--proxy-header" => { let v = take_val!("--proxy-header <PROXY_HEADERS>"); a.proxy_headers.push(v); }
            "-t" => { let v = take_val!("-t <TIMEOUT>");
                a.timeout = Some(match parse_duration(&v) { Ok(d)=>d, Err(e)=>return value_err("-t <TIMEOUT>", &v, &e) }); }
            "--connect-timeout" => { let v = take_val!("--connect-timeout <CONNECT_TIMEOUT>");
                a.connect_timeout = match parse_duration(&v) { Ok(d)=>d, Err(e)=>return value_err("--connect-timeout <CONNECT_TIMEOUT>", &v, &e) }; }
            "-A" => { a.accept_header = Some(take_val!("-A <ACCEPT_HEADER>")); }
            "-d" => { a.body_string = Some(take_val!("-d <BODY_STRING>")); }
            "-D" => { a.body_path = Some(PathBuf::from(take_val!("-D <BODY_PATH>"))); }
            "-Z" => { a.body_path_lines = Some(PathBuf::from(take_val!("-Z <BODY_PATH_LINES>"))); }
            "-F" | "--form" => { let v = take_val!("--form <FORM>"); a.form.push(v); }
            "-T" => { a.content_type = Some(take_val!("-T <CONTENT_TYPE>")); }
            "-a" => { a.basic_auth = Some(take_val!("-a <BASIC_AUTH>")); }
            "--aws-session" => { a.aws_session = Some(take_val!("--aws-session <AWS_SESSION>")); }
            "--aws-sigv4" => { a.aws_sigv4 = Some(take_val!("--aws-sigv4 <AWS_SIGV4>")); }
            "-x" => { a.proxy = Some(take_val!("-x <PROXY>")); }
            "--proxy-http-version" => { a.proxy_http_version = Some(take_val!("--proxy-http-version <PROXY_HTTP_VERSION>")); }
            "--proxy-http2" => { a.proxy_http2 = true; }
            "--http-version" => { a.http_version = Some(take_val!("--http-version <HTTP_VERSION>")); }
            "--http2" => {
                if seen_http2 { return dup_err("--http2"); }
                seen_http2 = true; a.http2 = true;
            }
            "--host" => { a.host = Some(take_val!("--host <HOST>")); }
            "--disable-compression" => { a.disable_compression = true; }
            "-r" | "--redirect" => { let v = take_val!("--redirect <REDIRECT>");
                a.redirect = match v.parse::<usize>() { Ok(n)=>n, Err(e)=>return value_err("--redirect <REDIRECT>", &v, &e.to_string()) }; }
            "--disable-keepalive" => {
                if seen_disable_keepalive { return dup_err("--disable-keepalive"); }
                seen_disable_keepalive = true; a.disable_keepalive = true;
            }
            "--no-pre-lookup" => { a.no_pre_lookup = true; }
            "--ipv6" => { a.ipv6 = true; }
            "--ipv4" => { a.ipv4 = true; }
            "--cacert" => { a.cacert = Some(PathBuf::from(take_val!("--cacert <CACERT>"))); }
            "--cert" => { a.cert = Some(PathBuf::from(take_val!("--cert <CERT>"))); }
            "--key" => { a.key = Some(PathBuf::from(take_val!("--key <KEY>"))); }
            "--insecure" => { a.insecure = true; }
            "--connect-to" => { let v = take_val!("--connect-to <CONNECT_TO>"); a.connect_to.push(v); }
            "--no-color" => { a.no_color = true; }
            "--unix-socket" => { a.unix_socket = Some(PathBuf::from(take_val!("--unix-socket <UNIX_SOCKET>"))); }
            "--stats-success-breakdown" => { a.stats_success_breakdown = true; }
            "--db-url" => { a.db_url = Some(take_val!("--db-url <DB_URL>")); }
            "--debug" => {
                if seen_debug { return dup_err("--debug"); }
                seen_debug = true; a.debug = true;
                if url.is_none() { required_option = Some("--debug".to_string()); }
            }
            "-o" | "--output" => { let v = take_val!("--output <OUTPUT>"); a.output = Some(PathBuf::from(v)); }
            "--output-format" => {
                if seen_output_format { return dup_err("--output-format <OUTPUT_FORMAT>"); }
                seen_output_format = true;
                let v = take_val!("--output-format <OUTPUT_FORMAT>");
                a.output_format = match v.as_str() {
                    "text" => OutputFormat::Text,
                    "json" => OutputFormat::Json,
                    "csv" => OutputFormat::Csv,
                    "quiet" => OutputFormat::Quiet,
                    _ => return ParseResult::UsageError(
                        format!("invalid value '{}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: text, json, csv, quiet]", v),
                        UsageContext { show_usage: false, ..Default::default() },
                    ),
                };
            }
            "-u" | "--time-unit" => {
                let v = take_val!("--time-unit <TIME_UNIT>");
                a.time_unit = Some(match v.as_str() {
                    "ns" => TimeUnit::Ns, "us" => TimeUnit::Us, "ms" => TimeUnit::Ms,
                    "s"  => TimeUnit::S,  "m"  => TimeUnit::M,  "h"  => TimeUnit::H,
                    _ => return ParseResult::UsageError(
                        format!("invalid value '{}' for '--time-unit <TIME_UNIT>'\n  [possible values: ns, us, ms, s, m, h]", v),
                        UsageContext { show_usage: false, ..Default::default() },
                    ),
                });
            }
            other => {
                if !other.starts_with('-') {
                    if url.is_none() { url = Some(other.to_string()); }
                    else { return unexpected(other, true); }
                } else {
                    return unexpected(other, url.is_some());
                }
            }
        }
        i += 1;
    }

    match url {
        Some(u) => { a.url = u; ParseResult::Args(Box::new(a)) }
        None => {
            let mut extra = vec![];
            if let Some(s) = required_option { extra.push(s); }
            ParseResult::UsageError(
                "the following required arguments were not provided:\n  <URL>".to_string(),
                UsageContext {
                    show_usage: true,
                    show_options: extra.is_empty(),
                    extra_positional: extra,
                },
            )
        }
    }
}

fn unexpected(arg: &str, has_url: bool) -> ParseResult {
    let tip = if arg.starts_with("--") {
        format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", arg, arg)
    } else { String::new() };
    let ctx = if has_url {
        UsageContext { show_usage: true, show_options: false, extra_positional: vec![] }
    } else {
        UsageContext { show_usage: true, show_options: true, extra_positional: vec![] }
    };
    ParseResult::UsageError(format!("unexpected argument '{}' found{}", arg, tip), ctx)
}

fn value_err(flag: &str, val: &str, err: &str) -> ParseResult {
    ParseResult::UsageError(
        format!("invalid value '{}' for '{}': {}", val, flag, err),
        UsageContext { show_usage: false, ..Default::default() },
    )
}

fn dup_err(flag: &str) -> ParseResult {
    ParseResult::UsageError(
        format!("the argument '{}' cannot be used multiple times", flag),
        UsageContext { show_usage: true, show_options: true, extra_positional: vec![] },
    )
}

fn parse_nreq(s: &str) -> Result<usize, String> {
    if let Some(rest) = s.strip_suffix('k').or_else(|| s.strip_suffix('K')) {
        rest.parse::<usize>().map(|n| n * 1_000).map_err(|e| e.to_string())
    } else if let Some(rest) = s.strip_suffix('m').or_else(|| s.strip_suffix('M')) {
        rest.parse::<usize>().map(|n| n * 1_000_000).map_err(|e| e.to_string())
    } else {
        s.parse::<usize>().map_err(|e| e.to_string())
    }
}

fn parse_duration(s: &str) -> Result<Duration, String> {
    let mut split = 0usize;
    for (idx, ch) in s.char_indices() {
        if ch.is_ascii_digit() || ch == '.' { split = idx + ch.len_utf8(); }
        else { break; }
    }
    if split == 0 { return Err("expected number at 0".to_string()); }
    let num_str = &s[..split];
    let unit = &s[split..];
    let num: f64 = num_str.parse().map_err(|_| "expected number at 0".to_string())?;
    let secs = match unit {
        "ns" => num * 1e-9, "us" | "µs" => num * 1e-6, "ms" => num * 1e-3,
        "s" | "" => num, "m" => num * 60.0, "h" => num * 3600.0, "d" => num * 86400.0,
        _ => return Err(format!("unknown time unit '{}'", unit)),
    };
    if secs < 0.0 { return Err("negative duration".to_string()); }
    Ok(Duration::from_secs_f64(secs))
}

pub fn format_usage(exe: &str, ctx: &UsageContext) -> String {
    let mut s = format!("Usage: {}", exe);
    if ctx.show_options { s.push_str(" [OPTIONS]"); }
    for opt in &ctx.extra_positional { s.push_str(&format!(" {}", opt)); }
    s.push_str(" <URL>");
    s
}

pub fn print_help_to(exe: &str, out: &mut dyn std::io::Write) -> std::io::Result<()> {
    out.write_all(HELP_TEXT.replace("{EXE}", exe).as_bytes())
}

pub fn emit_usage_error(exe: &str, msg: &str, ctx: &UsageContext) -> ExitCode {
    eprintln!("error: {}", msg);
    eprintln!();
    if ctx.show_usage {
        eprintln!("{}", format_usage(exe, ctx));
        eprintln!();
    }
    eprintln!("For more information, try '--help'.");
    ExitCode::from(2)
}

pub fn emit_empty_args_error(exe: &str) -> ExitCode {
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = print_help_to(exe, &mut lock);
    ExitCode::from(2)
}
