            "--key" => { a.key = Some(PathBuf::from(take_val!("--key <KEY>"))); }
            "--insecure" => { a.insecure = true; }
            "--connect-to" => { let v = take_val!("--connect-to <CONNECT_TO>"); a.connect_to.push(v); }
            "--no-color" => { a.no_color = true; }
            "--unix-socket" => { a.unix_socket = Some(PathBuf::from(take_val!("--unix-socket <UNIX_SOCKET>"))); }
            "--stats-success-breakdown" => { a.stats_success_breakdown = true; }
            "--db-url" => { a.db_url = Some(take_val!("--db-url <DB_URL>")); }
            "--debug" => {
                if seen_debug { return dup_err("--debug"); }
                seen_debug = true; a.debug = true;
                if url.is_none() { required_option = Some("--debug".to_string()); }
            }
            "-o" | "--output" => { let v = take_val!("--output <OUTPUT>"); a.output = Some(PathBuf::from(v)); }
            "--output-format" => {
                if seen_output_format { return dup_err("--output-format <OUTPUT_FORMAT>"); }
                seen_output_format = true;
                let v = take_val!("--output-format <OUTPUT_FORMAT>");
                a.output_format = match v.as_str() {
                    "text" => OutputFormat::Text,
                    "json" => OutputFormat::Json,
                    "csv" => OutputFormat::Csv,
                    "quiet" => OutputFormat::Quiet,
                    _ => return ParseResult::UsageError(
                        format!("invalid value '{}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: text, json, csv, quiet]", v),
                        UsageContext { show_usage: false, ..Default::default() },
                    ),
                };
            }
            "-u" | "--time-unit" => {
                let v = take_val!("--time-unit <TIME_UNIT>");
                a.time_unit = Some(match v.as_str() {
                    "ns" => TimeUnit::Ns, "us" => TimeUnit::Us, "ms" => TimeUnit::Ms,
                    "s"  => TimeUnit::S,  "m"  => TimeUnit::M,  "h"  => TimeUnit::H,
                    _ => return ParseResult::UsageError(
                        format!("invalid value '{}' for '--time-unit <TIME_UNIT>'\n  [possible values: ns, us, ms, s, m, h]", v),
                        UsageContext { show_usage: false, ..Default::default() },
                    ),
                });
            }
            other => {
                if !other.starts_with('-') {
                    if url.is_none() { url = Some(other.to_string()); }
                    else { return unexpected(other, true); }
                } else {
                    return unexpected(other, url.is_some());
                }
            }
        }
        i += 1;
    }

    match url {
        Some(u) => { a.url = u; ParseResult::Args(Box::new(a)) }
        None => {
            let mut extra = vec![];
            if let Some(s) = required_option { extra.push(s); }
            ParseResult::UsageError(
                "the following required arguments were not provided:\n  <URL>".to_string(),
                UsageContext {
                    show_usage: true,
                    show_options: extra.is_empty(),
                    extra_positional: extra,
                },
            )
        }
    }
}

fn unexpected(arg: &str, has_url: bool) -> ParseResult {
    let tip = if arg.starts_with("--") {
        format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", arg, arg)
    } else { String::new() };
    let ctx = if has_url {
        UsageContext { show_usage: true, show_options: false, extra_positional: vec![] }
    } else {
        UsageContext { show_usage: true, show_options: true, extra_positional: vec![] }
    };
    ParseResult::UsageError(format!("unexpected argument '{}' found{}", arg, tip), ctx)
}

fn value_err(flag: &str, val: &str, err: &str) -> ParseResult {
    ParseResult::UsageError(
        format!("invalid value '{}' for '{}': {}", val, flag, err),
        UsageContext { show_usage: false, ..Default::default() },
    )
}

fn dup_err(flag: &str) -> ParseResult {
    ParseResult::UsageError(
        format!("the argument '{}' cannot be used multiple times", flag),
        UsageContext { show_usage: true, show_options: true, extra_positional: vec![] },
    )
}

fn parse_nreq(s: &str) -> Result<usize, String> {
    if let Some(rest) = s.strip_suffix('k').or_else(|| s.strip_suffix('K')) {
        rest.parse::<usize>().map(|n| n * 1_000).map_err(|e| e.to_string())
    } else if let Some(rest) = s.strip_suffix('m').or_else(|| s.strip_suffix('M')) {
        rest.parse::<usize>().map(|n| n * 1_000_000).map_err(|e| e.to_string())
    } else {
        s.parse::<usize>().map_err(|e| e.to_string())
    }
}

fn parse_duration(s: &str) -> Result<Duration, String> {
    let mut split = 0usize;
    for (idx, ch) in s.char_indices() {
        if ch.is_ascii_digit() || ch == '.' { split = idx + ch.len_utf8(); }
        else { break; }
    }
    if split == 0 { return Err("expected number at 0".to_string()); }
    let num_str = &s[..split];
    let unit = &s[split..];
    let num: f64 = num_str.parse().map_err(|_| "expected number at 0".to_string())?;
    let secs = match unit {
        "ns" => num * 1e-9, "us" | "µs" => num * 1e-6, "ms" => num * 1e-3,
        "s" | "" => num, "m" => num * 60.0, "h" => num * 3600.0, "d" => num * 86400.0,
        _ => return Err(format!("unknown time unit '{}'", unit)),
    };
    if secs < 0.0 { return Err("negative duration".to_string()); }
    Ok(Duration::from_secs_f64(secs))
}

pub fn format_usage(exe: &str, ctx: &UsageContext) -> String {
    let mut s = format!("Usage: {}", exe);
    if ctx.show_options { s.push_str(" [OPTIONS]"); }
    for opt in &ctx.extra_positional { s.push_str(&format!(" {}", opt)); }
    s.push_str(" <URL>");
    s
}

pub fn print_help_to(exe: &str, out: &mut dyn std::io::Write) -> std::io::Result<()> {
    out.write_all(HELP_TEXT.replace("{EXE}", exe).as_bytes())
}

pub fn emit_usage_error(exe: &str, msg: &str, ctx: &UsageContext) -> ExitCode {
    eprintln!("error: {}", msg);
    eprintln!();
    if ctx.show_usage {
        eprintln!("{}", format_usage(exe, ctx));
        eprintln!();
    }
    eprintln!("For more information, try '--help'.");
    ExitCode::from(2)
}

pub fn emit_empty_args_error(exe: &str) -> ExitCode {
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = print_help_to(exe, &mut lock);
    ExitCode::from(2)
}
